-- Тема 05: варианты ответов выровнены по длине и форме (72 исправлений в 24 вопросах), ключи не меняются.
-- Источник: scripts/questions/076_option_length_topic05.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Что хранит снимок данных?', 'Физическую копию всех строк таблицы', 'Физическую копию всех строк таблицы на момент создания', 'Снимок не копирует данные: видимость определяется по номерам транзакций.', NULL),
        ('option', 'Что хранит снимок данных?', 'Копию буферного кеша', 'Копию содержимого буферного кеша на этот момент', 'Буферный кеш общий для всех, снимок его не копирует.', NULL),
        ('option', 'Что хранит снимок данных?', 'Границы номеров транзакций и список транзакций, не завершившихся к моменту создания снимка', 'Границы номеров транзакций и список незавершённых', 'Снимок содержит нижнюю и верхнюю границы номеров и список незавершённых транзакций между ними. Эти сведения вместе со статусами транзакций позволяют определить видимость версий строк.', 'Снимок содержит нижнюю и верхнюю границы номеров транзакций и список транзакций, не завершившихся к моменту создания снимка. Эти сведения вместе со статусами транзакций позволяют определить видимость версий строк.'),
        ('option', 'Что хранит снимок данных?', 'Список заблокированных строк', 'Список строк, заблокированных другими транзакциями', 'Признаки блокировки хранятся в самих версиях строк, а не в снимке.', NULL),
        ('option', 'Как PostgreSQL ведёт себя на уровне Read Uncommitted?', 'Допускает грязное чтение', 'Допускает грязное чтение, как в стандарте SQL', 'Грязного чтения в PostgreSQL нет ни на одном уровне.', NULL),
        ('option', 'Как PostgreSQL ведёт себя на уровне Read Uncommitted?', 'Работает как Read Committed', 'Работает так же, как Read Committed', 'Уровень принимается, но ведёт себя как Read Committed.', NULL),
        ('option', 'Как PostgreSQL ведёт себя на уровне Read Uncommitted?', 'Выдаёт ошибку', 'Выдаёт ошибку: такой уровень не поддерживается', 'Ошибки нет, уровень принимается.', NULL),
        ('option', 'Когда строится снимок данных на уровне Repeatable Read?', 'В начале каждого оператора', 'В начале каждого оператора транзакции', 'Так работает Read Committed.', NULL),
        ('option', 'Когда строится снимок данных на уровне Repeatable Read?', 'При фиксации транзакции', 'В момент фиксации транзакции', 'При фиксации снимок уже не нужен.', NULL),
        ('option', 'Когда строится снимок данных на уровне Repeatable Read?', 'При подключении сеанса', 'При подключении сеанса к серверу', 'Снимок относится к транзакции, а не к сеансу.', NULL),
        ('option', 'Когда строится снимок данных на уровне Repeatable Read?', 'При выполнении первого оператора, которому нужен снимок данных, а не при BEGIN', 'При первом операторе с данными, не при BEGIN', 'Снимок строится первым оператором, которому нужны данные (BEGIN его не создаёт), и действует до конца транзакции.', NULL),
        ('option', 'Что физически происходит при UPDATE строки?', 'Строка перезаписывается на месте', 'Строка перезаписывается на месте новым значением', 'Многоверсионность не перезаписывает строку на месте.', NULL),
        ('option', 'Что физически происходит при UPDATE строки?', 'Старая версия сразу физически удаляется', 'Старая версия сразу физически удаляется со страницы', 'Старая версия остаётся, пока её не уберёт очистка.', NULL),
        ('option', 'Что физически происходит при UPDATE строки?', 'Копируется вся страница целиком', 'Копируется вся страница целиком в новое место', 'Создаётся новая версия строки, а не копия страницы.', NULL),
        ('option', 'Что физически происходит при UPDATE строки?', 'Старая версия помечается удалённой, создаётся новая версия строки', 'Старая версия помечается удалённой, создаётся новая', 'У старой версии заполняется xmax, а новая версия размещается на той же или другой странице.', NULL),
        ('option', 'Что такое горизонт очистки?', 'Максимальный размер таблицы перед очисткой', 'Максимальный размер таблицы перед запуском очистки', 'Горизонт — это номер транзакции, а не размер.', NULL),
        ('option', 'Что такое горизонт очистки?', 'Номер транзакции, удалённые до которого версии строк уже не видны ни в одном снимке', 'Номер транзакции: удалённое до него не видно снимкам', 'Версии, удалённые до горизонта, не нужны ни одному снимку и могут быть вычищены.', 'Номер транзакции, удалённые до которого версии строк уже не видны ни в одном снимке: такие версии не нужны ни одному снимку и могут быть вычищены.'),
        ('option', 'Что такое горизонт очистки?', 'Время следующего запуска автоочистки', 'Время следующего запуска автоочистки для таблицы', 'Расписание автоочистки — отдельное понятие.', NULL),
        ('option', 'Что такое горизонт очистки?', 'Номер последней контрольной точки', 'Номер последней контрольной точки в журнале', 'Контрольная точка относится к журналу, а не к видимости версий.', NULL),
        ('option', 'Чем опасна долгая транзакция?', 'Может удерживать горизонт очистки и способствовать разрастанию таблиц и индексов', 'Может удерживать горизонт очистки и раздувать таблицы', 'Это происходит, если транзакция удерживает старый снимок или назначенный номер транзакции. Тогда часть старых версий ещё нельзя удалить очисткой.', 'Это происходит, если транзакция удерживает старый снимок или назначенный номер транзакции: часть старых версий ещё нельзя удалить очисткой, и таблицы и индексы разрастаются.'),
        ('option', 'Чем опасна долгая транзакция?', 'Блокирует чтение всех таблиц', 'Блокирует чтение всех таблиц базы данных', 'Обычные изменения строк не блокируют чтение; чтение таблицы мешает только блокировка ACCESS EXCLUSIVE.', NULL),
        ('option', 'Чем опасна долгая транзакция?', 'Останавливает запись журнала', 'Останавливает запись журнала предзаписи на диск', 'Запись журнала не останавливается.', NULL),
        ('option', 'Чем опасна долгая транзакция?', 'Сбрасывает накопительную статистику', 'Сбрасывает накопительную статистику сервера', 'Накопительная статистика от этого не сбрасывается.', NULL),
        ('option', 'В каком случае транзакция будет ждать освобождения блокировки строки?', 'При чтении строки, которую изменяет другая транзакция', 'При чтении строки, которую меняет другая транзакция', 'Писатели не блокируют читателей: читается подходящая версия строки.', NULL),
        ('option', 'В каком случае транзакция будет ждать освобождения блокировки строки?', 'При любом SELECT из изменяемой таблицы', 'При любом SELECT из таблицы, где идут изменения', 'Обычное чтение не ждёт изменений.', NULL),
        ('option', 'В каком случае транзакция будет ждать освобождения блокировки строки?', 'Когда пытается изменить строку, уже изменённую другой незафиксированной транзакцией', 'Когда пытается изменить строку, уже изменённую другой', 'Изменить строку можно, когда первая транзакция завершится или откатится к более ранней точке сохранения.', 'Когда пытается изменить строку, уже изменённую другой незафиксированной транзакцией. Изменить строку можно, когда первая транзакция завершится или откатится к более ранней точке сохранения.'),
        ('option', 'Почему откат транзакции в PostgreSQL выполняется быстро, без отмены каждого изменения?', 'Все изменения до COMMIT хранятся только в памяти', 'Все изменения до COMMIT хранятся в памяти процесса', 'Изменения сразу попадают в страницы, они не ждут COMMIT.', NULL),
        ('option', 'Почему откат транзакции в PostgreSQL выполняется быстро, без отмены каждого изменения?', 'Откат выполняется фоновым процессом через WAL', 'Откат выполняется фоновым процессом по записям WAL', 'Отдельного фонового процесса отката нет.', NULL),
        ('option', 'Почему откат транзакции в PostgreSQL выполняется быстро, без отмены каждого изменения?', 'При откате отключается журналирование', 'При откате журналирование отключается на время работы', 'При откате журналирование не отключается.', NULL),
        ('option', 'Почему откат транзакции в PostgreSQL выполняется быстро, без отмены каждого изменения?', 'Не нужно восстанавливать каждую старую версию: транзакция помечается прерванной в clog, а лишние версии строк потом убирает очистка', 'Версии не нужно возвращать: статус прерванной в clog', 'Версии строк прерванной транзакции не видны по её статусу, поэтому переписывать их обратно не нужно.', 'Транзакция помечается прерванной в clog, а ненужные версии строк потом убирает очистка. Версии прерванной транзакции не видны по её статусу, поэтому переписывать их обратно не нужно.'),
        ('option', 'Что верно для уровня изоляции Read Committed?', 'Два одинаковых запроса в одной транзакции могут вернуть разные данные', 'Два одинаковых запроса могут вернуть разные данные', 'Между запросами другие транзакции могут зафиксировать изменения.', NULL),
        ('option', 'Что верно для блокировок в PostgreSQL?', 'Изменение строки блокирует её чтение', 'Изменение строки блокирует её чтение другими', 'Читатель не ждёт: он видит подходящую версию строки.', NULL),
        ('option', 'Что верно для блокировок в PostgreSQL?', 'Обычные блокировки строк и таблиц освобождаются при завершении транзакции, если не были освобождены раньше откатом к точке сохранения', 'Обычные блокировки освобождаются при завершении транзакции', 'Обычные блокировки держатся до конца транзакции или до отката к более ранней точке сохранения; рекомендательные блокировки сеанса — до конца сеанса.', 'Обычные блокировки строк и таблиц держатся до конца транзакции или до отката к более ранней точке сохранения; рекомендательные блокировки сеанса — до конца сеанса.'),
        ('option', 'Что верно для блокировок в PostgreSQL?', 'Обычный SELECT без FOR UPDATE и FOR SHARE не мешает другим транзакциям читать и изменять строки', 'Обычный SELECT не мешает другим читать и изменять строки', 'SELECT получает блокировку ACCESS SHARE: она совместима с обычными изменениями строк, но конфликтует с ACCESS EXCLUSIVE, например у DROP TABLE.', 'Обычный SELECT без FOR UPDATE и FOR SHARE получает блокировку ACCESS SHARE: она совместима с обычными изменениями строк, но конфликтует с ACCESS EXCLUSIVE, например у DROP TABLE.'),
        ('option', 'Что должно уметь приложение, работающее на уровне изоляции Serializable?', 'Работать в каждой транзакции только с одной таблицей', 'Работать в каждой транзакции с одной таблицей', 'Такого ограничения нет.', NULL),
        ('option', 'Что должно уметь приложение, работающее на уровне изоляции Serializable?', 'Явно блокировать все читаемые строки', 'Явно блокировать все строки, которые она читает', 'Не требуется: уровень сам обеспечивает полную изоляцию.', NULL),
        ('option', 'Чем помечается версия строки при её создании?', 'Номером страницы, на которой она лежит', 'Номером страницы, на которой версия лежит', 'Положение версии на странице не определяет её время действия.', NULL),
        ('option', 'Чем помечается версия строки при её создании?', 'Временем по часам сервера', 'Временем создания по часам сервера', 'Вместо времени используются возрастающие номера транзакций.', NULL),
        ('option', 'Чем помечается версия строки при её создании?', 'Номером транзакции, создавшей эту версию (командой INSERT или UPDATE)', 'Номером создавшей её транзакции', 'Время действия версий измеряется номерами транзакций.', NULL),
        ('option', 'Что происходит с версией строки при выполнении DELETE?', 'Она переносится в toast-таблицу', 'Она переносится в TOAST-таблицу этой таблицы', 'TOAST служит для длинных значений, а не для удалённых строк.', NULL),
        ('option', 'Что происходит с версией строки при выполнении DELETE?', 'Она переносится в журнал предзаписи', 'Она переносится в журнал предзаписи сервера', 'В журнал пишется запись об изменении, сама версия остаётся в таблице.', NULL),
        ('option', 'Что происходит с версией строки при выполнении DELETE?', 'Она помечается номером удалившей транзакции и физически остаётся на месте', 'Она помечается номером удалившей транзакции', 'Её ещё могут видеть другие снимки, а при откате она снова станет актуальной.', 'Версия помечается номером удалившей транзакции и физически остаётся на месте: её ещё могут видеть другие снимки, а при откате она снова станет актуальной.'),
        ('option', 'На каком уровне определяется горизонт очистки?', 'Один на весь кластер', 'Один на весь кластер баз данных', 'В курсе горизонт рассматривается для каждой базы отдельно.', NULL),
        ('option', 'На каком уровне определяется горизонт очистки?', 'Отдельно для каждого сеанса', 'Отдельно для каждого сеанса клиента', 'Сеанс лишь может удерживать горизонт своей долгой транзакцией.', NULL),
        ('option', 'На каком уровне определяется горизонт очистки?', 'Отдельно для каждой базы данных', 'Отдельно для каждой базы данных кластера', 'Для обычных таблиц горизонт определяется по транзакциям базы данных. Для общих и локальных каталогов и временных таблиц правила особые.', NULL),
        ('option', 'На каком уровне определяется горизонт очистки?', 'Отдельно для каждой таблицы', 'Отдельно для каждой таблицы базы', 'Горизонт определяется по транзакциям базы, а не по таблице.', NULL),
        ('option', 'Транзакция A прочитала таблицу и ещё не завершилась. Что произойдёт, если во втором сеансе выполнить DROP TABLE для этой таблицы?', 'DROP TABLE сразу завершится ошибкой', 'DROP TABLE сразу завершится ошибкой блокировки', 'По умолчанию команда ждёт блокировку (если не задан lock_timeout).', NULL),
        ('option', 'Транзакция A прочитала таблицу и ещё не завершилась. Что произойдёт, если во втором сеансе выполнить DROP TABLE для этой таблицы?', 'Транзакция A будет прервана', 'Транзакция A будет прервана сервером', 'Ждёт тот, кто запрашивает несовместимую блокировку, а не наоборот.', NULL),
        ('option', 'Обычная блокировка строки или таблицы была получена после установки точки сохранения. Когда она будет снята при откате к этой точке?', 'Через время, заданное deadlock_timeout', 'Через deadlock_timeout после отката к точке', 'Этот параметр относится к проверке взаимоблокировок.', NULL),
        ('option', 'Обычная блокировка строки или таблицы была получена после установки точки сохранения. Когда она будет снята при откате к этой точке?', 'Никогда, её нужно снять вручную', 'Её нужно снять вручную командой администратора', 'Все блокировки снимаются автоматически.', NULL),
        ('option', 'Обычная блокировка строки или таблицы была получена после установки точки сохранения. Когда она будет снята при откате к этой точке?', 'Сразу при откате к точке сохранения', 'Сразу при откате к этой точке сохранения', 'Так блокировки, полученные после точки сохранения, освобождаются раньше конца транзакции.', NULL),
        ('option', 'Обычная блокировка строки или таблицы была получена после установки точки сохранения. Когда она будет снята при откате к этой точке?', 'Только при завершении всей транзакции', 'Вместе с завершением всей транзакции', 'Это верно для остальных блокировок, но не для полученных после точки сохранения.', NULL),
        ('option', 'Две транзакции без точек сохранения захватили разные строки, а затем каждая запросила блокировку строки, удерживаемой другой. Как PostgreSQL разрешает такую взаимоблокировку?', 'Обнаруживает цикл ожиданий и прерывает одну из транзакций с ошибкой', 'Обнаруживает цикл и прерывает одну из транзакций', 'Это освобождает её блокировки и позволяет другой транзакции продолжить работу.', NULL),
        ('option', 'Две транзакции без точек сохранения захватили разные строки, а затем каждая запросила блокировку строки, удерживаемой другой. Как PostgreSQL разрешает такую взаимоблокировку?', 'Автоматически фиксирует обе транзакции', 'Автоматически фиксирует обе транзакции сразу', 'Сервер не фиксирует транзакции вместо приложения для разрешения взаимоблокировки.', NULL),
        ('option', 'Две транзакции без точек сохранения захватили разные строки, а затем каждая запросила блокировку строки, удерживаемой другой. Как PostgreSQL разрешает такую взаимоблокировку?', 'Всегда прерывает ту транзакцию, которая началась позже', 'Прерывает ту транзакцию, которая началась позже', 'Полагаться на выбор конкретной транзакции нельзя.', NULL),
        ('option', 'Две транзакции без точек сохранения захватили разные строки, а затем каждая запросила блокировку строки, удерживаемой другой. Как PostgreSQL разрешает такую взаимоблокировку?', 'Обе ждут бесконечно, пока администратор не снимет блокировки', 'Обе ждут бесконечно до вмешательства администратора', 'PostgreSQL автоматически обнаруживает взаимоблокировки.', NULL),
        ('option', 'Что такое «грязное чтение»?', 'Чтение изменений другой транзакции, которые ещё не зафиксированы', 'Чтение чужих изменений до фиксации', 'Стандарт SQL допускает его на уровне Read Uncommitted, но в PostgreSQL этот уровень работает как Read Committed, и грязных чтений нет.', NULL),
        ('option', 'Что такое «грязное чтение»?', 'Чтение данных из грязного буфера', 'Чтение данных из грязного буфера кеша', 'Грязный буфер — изменённая страница в памяти; это другое понятие.', NULL),
        ('option', 'Строка уже зафиксирована. Транзакция A изменила её командой UPDATE и ещё не завершилась. Второй сеанс работает на уровне Read Committed и обращается к этой строке. Что произойдёт?', 'Обычный SELECT этой строки будет ждать завершения транзакции A', 'Обычный SELECT будет ждать завершения транзакции A', 'Многоверсионность позволяет читать без ожидания. Ждать может SELECT с блокирующим предложением, например FOR UPDATE или FOR SHARE, если запрошенная блокировка конфликтует с блокировкой A.', NULL),
        ('option', 'Строка уже зафиксирована. Транзакция A изменила её командой UPDATE и ещё не завершилась. Второй сеанс работает на уровне Read Committed и обращается к этой строке. Что произойдёт?', 'Обычный SELECT этой строки не будет ждать блокировку и прочитает версию до изменения', 'SELECT не будет ждать и прочитает версию до изменения', 'Чтение берёт версию строки, подходящую по снимку, и блокировку строки не ждёт.', NULL),
        ('option', 'В транзакции после SAVEPOINT s вставлена строка. Какой номер транзакции окажется в xmin этой строки?', 'Собственный номер подтранзакции, отличный от номера основной транзакции', 'Номер подтранзакции, а не основной транзакции', 'Вставляющая подтранзакция получает свой номер, он и записывается в xmin. Откат к точке s отменяет работу после неё, включая вложенные подтранзакции.', NULL),
        ('option', 'В транзакции после SAVEPOINT s вставлена строка. Какой номер транзакции окажется в xmin этой строки?', 'Номер основной транзакции', 'Номер основной транзакции без подтранзакции в xmin', 'В xmin записывается номер вставляющей подтранзакции; её связь с основной транзакцией учитывается отдельно.', NULL),
        ('option', 'Транзакция A на уровне Read Committed прочитала строку. Транзакция B изменила эту строку командой UPDATE и ещё не зафиксировала изменения. A снова выполняет SELECT xmin, xmax, * FROM t. Что она увидит?', 'Старую версию с xmax = 0, номер B появится там только после фиксации', 'Старую версию с xmax = 0 до фиксации транзакции B', 'xmax записывается сразу при UPDATE, а видимость решают снимок и статус B.', NULL),
        ('option', 'Транзакция A на уровне Read Committed прочитала строку. Транзакция B изменила эту строку командой UPDATE и ещё не зафиксировала изменения. A снова выполняет SELECT xmin, xmax, * FROM t. Что она увидит?', 'Старую версию строки, в её xmax уже записан номер транзакции B', 'Старую версию строки, в xmax уже номер транзакции B', 'B заменила версию, но её изменения ещё не зафиксированы, поэтому в снимок A они не попадают.', NULL),
        ('option', 'Снимок данных построен, когда все упомянутые транзакции уже завершились. Какие версии строки в него попадут?', 'Транзакция xmin зафиксирована, xmax = 0', 'xmin зафиксирована, xmax равен нулю', 'Актуальная версия: её никто не удалял и не заменял.', NULL),
        ('option', 'Снимок данных построен, когда все упомянутые транзакции уже завершились. Какие версии строки в него попадут?', 'Транзакции xmin и xmax зафиксированы', 'Транзакции xmin и xmax обе зафиксированы к этому моменту', 'Версию удалили или заменили до создания снимка.', NULL),
        ('option', 'Снимок данных построен, когда все упомянутые транзакции уже завершились. Какие версии строки в него попадут?', 'Транзакция xmin прервана', 'Транзакция xmin отменена, версия осталась на странице', 'Версию создала отменённая транзакция, её как будто не было.', NULL),
        ('option', 'Снимок данных построен, когда все упомянутые транзакции уже завершились. Какие версии строки в него попадут?', 'Транзакция xmin зафиксирована, транзакция xmax прервана', 'xmin зафиксирована, транзакция xmax отменена', 'Удаление или изменение отменено, версия остаётся актуальной.', NULL),
        ('option', 'Транзакция на уровне Repeatable Read уже час строит отчёт по таблице t1 и не завершается. Таблица t2 в той же базе всё это время активно обновляется. Что сможет сделать очистка с t2?', 'Не сможет убрать версии строк t2, ставшие неактуальными после создания снимка долгой транзакции', 'Не сможет убрать версии t2, ставшие неактуальными', 'Горизонт очистки один на базу, и его держит снимок долгой транзакции, хотя она не обращается к t2.', 'Очистка не уберёт версии строк t2, ставшие неактуальными после создания снимка долгой транзакции: горизонт очистки один на базу, и его держит этот снимок, хотя транзакция не обращается к t2.'),
        ('option', 'Транзакция на уровне Repeatable Read уже час строит отчёт по таблице t1 и не завершается. Таблица t2 в той же базе всё это время активно обновляется. Что сможет сделать очистка с t2?', 'Очистит t2 полностью, ведь долгая транзакция работает только с t1', 'Очистит t2 полностью: долгая транзакция читает t1', 'Очистка не знает, к каким таблицам транзакция обратится дальше.', NULL),
        ('option', 'Транзакция A изменила строку и ещё не завершилась. Транзакция B выполняет UPDATE той же строки и ждёт. Затем A фиксирует изменения. Что верно?', 'На уровне Repeatable Read UPDATE в B завершится ошибкой сериализации', 'На Repeatable Read UPDATE в B получит ошибку сериализации', 'Снимок B не видит изменений A, а менять версию, которой нет в снимке, нельзя. Транзакцию нужно повторить.', NULL),
        ('option', 'Транзакция A изменила строку и ещё не завершилась. Транзакция B выполняет UPDATE той же строки и ждёт. Затем A фиксирует изменения. Что верно?', 'На уровне Read Committed UPDATE в B продолжится: заново проверит условие WHERE на новой версии строки и, если условие выполняется, изменит её', 'На Read Committed UPDATE в B продолжится после проверки WHERE', 'Перепроверяется только эта строка, новый снимок не строится.', 'На Read Committed UPDATE в B продолжится: заново проверит условие WHERE на новой версии строки и, если оно выполняется, изменит её. Перепроверяется только эта строка, новый снимок не строится.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
